  /// Check if an official hardcoded paper is available
  static bool hasPaper(String exam, String year) {
    final ex = exam.toLowerCase();
    if (!ex.contains('utet') || ex.endsWith('2')) return false;
    return _papersJson.containsKey(year);
  }

  /// Get official paper with exact 1-150 questions in official order
  static ({List<Question> questions, Map<String, Passage> passages})? getPaper(String exam, String year) {
    if (!hasPaper(exam, year)) return null;
    final cacheKey = '${exam}_$year';
    if (_cache.containsKey(cacheKey)) {
      return _cache[cacheKey];
    }

    final raw = _papersJson[year];
    if (raw == null) return null;

    final List<dynamic> list = jsonDecode(raw);
    final questions = list
        .map((item) => Question.fromOfficialJson(item as Map<String, dynamic>))
        .toList();

    final Map<String, Passage> paperPassages = {};
    for (final q in questions) {
      if (q.passageId != null && allPassages.containsKey(q.passageId)) {
        paperPassages[q.passageId!] = allPassages[q.passageId!]!;
      }
    }

    final result = (questions: questions, passages: paperPassages);
    _cache[cacheKey] = result;
    return result;
  }

  /// Get specific passage by ID
  static Passage? getPassage(String pid) => allPassages[pid];

