    '2024': r'''[{"id":"utet_2024_q1","exams":"utet1","section":"cdp","topic":"भाषा विकास","q_hi":"बच्चों में भाषा का विकास एक निश्चित क्रम में होता है, वह है —","options_hi":["बोलना, पढ़ना, सुनना, लिखना","सुनना, बोलना, पढ़ना, लिखना","सुनना, बोलना, लिखना, पढ़ना","बोलना, सुनना, पढ़ना, लिखना"],"ans":1,"source":"UTET 2024 Q1","years":"2024","q_en":"Development of language in children occurs in a certain order, that is —","options_en":["Speaking, Reading, Listening, Writing","Listening, Speaking, Reading, Writing","Listening, Speaking, Writing, Reading","Speaking, Listening, Reading, Writing"]},{"id":"utet_2024_q2","exams":"utet1","section":"cdp","topic":"प्रसिद्ध कथन","q_hi":"\"शिक्षा मनोविज्ञान शैक्षणिक विकास का क्रमिक अध्ययन है।\" किसने कहा?","options_hi":["स्टीफन","स्किनर","क्रो एवं क्रो","मन"],"ans":0,"source":"UTET 2024 Q2","years":"2024","q_en":"\"Educational Psychology is a systematic study of educational growth.\" Who said?","options_en":["Stephen","Skinner","Crow & Crow","Munn"]},{"id":"utet_2024_q3","exams":"utet1","section":"cdp","topic":"अधिगम की प्रकृति","q_hi":"मानसिक आयु का प्रत्यय किसने दिया था?","options_hi":["स्टर्न","टर्मन","बिने-साइमन","बर्ट"],"ans":2,"source":"UTET 2024 Q3","years":"2024","q_en":"Who gave the concept of Mental Age?","options_en":["Stern","Terman","Binet-Simon","Burt"]},{"id":"utet_2024_q4","exams":"utet1","section":"cdp","topic":"अधिगम की प्रकृति","q_hi":"सी.डब्ल्यू.एस.एन. (C.W.S.N.) का सम्बन्ध है —","options_hi":["मजबूत आवश्यकता वाले बच्चों से","विशिष्ट आवश्यकता वाले बच्चों से","विशिष्ट कक्षा वाले बच्चों से","इनमें से कोई नहीं"],"ans":1,"source":"UTET 2024 Q4","years":"2024","q_en":"C.W.S.N. is related to —","options_en":["Children with strong needs","Children with special needs","Children with special class","None of these"]},{"id":"utet_2024_q5","exams":"utet1","section":"cdp","topic":"अधिगम की प्रकृति","q_hi":"क्रोध एवं भय प्रकार हैं —","options_hi":["अभिप्रेरणा के","संवेग के","परिकल्पना के","मूल प्रवृत्ति के"],"ans":1,"source"